#include <vector>
#include <sstream>
#include <algorithm>
using namespace std;
class DoublyListGrader {
public:
 static void setup(DoublyList& l,vector<int> values){DLLNode* prev=nullptr;for(int v:values){DLLNode* n=new DLLNode(v,prev,nullptr);if(prev)prev->setNext(n);else l.first=n;prev=n;}l.last=prev;l.count=values.size();}
 static vector<DLLNode*> nodes(DoublyList& l){vector<DLLNode*> n;DLLNode* p=l.first;for(int i=0;p&&i<50;++i){n.push_back(p);p=p->getNext();}return n;}
 static string check(DoublyList& l,const vector<int>& expected,const vector<DLLNode*>& oldNodes,int kind){
  auto now=nodes(l);bool valid=l.count==(int)expected.size()&&now.size()==expected.size();
  if(now.empty())valid=valid&&!l.first&&!l.last;
  else valid=valid&&l.first==now.front()&&l.last==now.back()&&!l.first->getPrev()&&!l.last->getNext();
  for(size_t i=0;i<now.size();++i){valid=valid&&i<expected.size()&&now[i]->getData()==expected[i];valid=valid&&now[i]->getPrev()==(i?now[i-1]:nullptr)&&now[i]->getNext()==(i+1<now.size()?now[i+1]:nullptr);}
  DLLNode* p=l.last;for(size_t i=now.size();i>0;--i){if(p!=now[i-1]){valid=false;break;}p=p->getPrev();}valid=valid&&!p;
  if(kind==2)valid=valid&&now==oldNodes;
  if(kind==1){size_t retained=0;for(auto n:oldNodes)if(find(now.begin(),now.end(),n)!=now.end())++retained;valid=valid&&retained==oldNodes.size();}
  if(kind==0){size_t retained=0;for(auto n:now)if(find(oldNodes.begin(),oldNodes.end(),n)!=oldNodes.end())++retained;valid=valid&&retained==now.size();}
  ostringstream out;out<<(valid?"PASS":"FAIL")<<"|[";for(size_t i=0;i<now.size();++i){if(i)out<<", ";out<<now[i]->getData();}out<<"]";if(!valid)out<<" (check values, links, count, and node identity)";
  l.first=nullptr;l.last=nullptr;l.count=0;return out.str();
 }
};

