{DoublyList l,other;DoublyListGrader::setup(l,{10,20});DoublyListGrader::setup(other,{});auto old=DoublyListGrader::nodes(l);auto oldOther=DoublyListGrader::nodes(other);l.deleteFirst();auto result=DoublyListGrader::check(l,{20},old,0);cout<<"TEST2|"<<result<<"\n";}
